    /// <summary>
    /// Returns the class the registration captured, which is the one an override
    /// chains up through.
    /// </summary>
    /// <param name="instance">The native <c>GstVideoEncoder</c>.</param>
    /// <returns>The parent class of the managed subclass.</returns>
    private static Gst.Video.VideoEncoderClassRaw* ParentClassOf(nint instance) =>
        (Gst.Video.VideoEncoderClassRaw*)Gst.GObject.SubclassRegistry.DescriptorFor(instance).ParentClass;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int OpenTrampoline(nint encoder)
    {
        try
        {
            if (Gst.GObject.Object.TryGetOrFabricate(encoder) is not VideoEncoder managed)
            {
                return (ChainUpOpen(encoder)) ? 1 : 0;
            }

            return (managed.OnOpen()) ? 1 : 0;
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return default;
        }
    }

